'use strict';

const {
    Strongmb,
    ApiError,
    AuthError,
    StrongmbError
} = require('../src/index');

const strongmb = new Strongmb('your_api_key_here');


(async () => {

    // ── User profile ──────────────────────────────────────────────────────────────
    try {
        const response = await strongmb.account.user();
        const account = response.data().account;

        console.log('Name:  ', account.name);
        console.log('Phone: ', account.phone);
        console.log('Status:', account.account_status);
        console.log('KYC:   ', account.kyc_status);
    } catch (err) {
        if (err instanceof AuthError) {
            console.error('Invalid API key.');
        } else if (err instanceof ApiError) {
            console.error('Error:', err.message);
        }
    }

   console.log('');


    // ── Wallets ───────────────────────────────────────────────────────────────────
    try {
        const response = await strongmb.account.wallets();

        for (const wallet of response.data().wallets) {
            console.log('Wallet: ', wallet.type);
            console.log('Balance: ₦' + wallet.balance.toLocaleString('en-NG', {
                minimumFractionDigits: 2
            }));
            console.log('Status: ', wallet.status);
            console.log('');
        }
    } catch (err) {
        if (err instanceof ApiError) {
            console.error('Error:', err.message);
        }
    }

 

    // ── Transaction history ───────────────────────────────────────────────────────
    try {
        const response = await strongmb.account.transactions();
        const data = response.data();

        console.log('Total transactions:', data.count);
        console.log('');

        for (const txn of data.transactions) {
            console.log(`[${txn.status}] ${txn.type.toUpperCase()} — ₦${txn.amount.toLocaleString('en-NG', { minimumFractionDigits: 2 })} (${txn.reference})`);
        }
    } catch (err) {
        if (err instanceof ApiError) {
            console.error('Error:', err.message);
        }
    }

  
    // ── Single transaction by reference ──────────────────────────────────────────
    try {
        const response = await strongmb.account.transaction('SMB-D-2605151149272145-E4B08DDB');
        const txn = response.data().transaction;

        console.log('Reference:', txn.reference);
        console.log('Type:     ', txn.type);
        console.log('Amount:   ₦' + txn.amount.toLocaleString('en-NG', {
            minimumFractionDigits: 2
        }));
        console.log('Status:   ', txn.status);
    } catch (err) {
        if (err instanceof ApiError) {
            console.error(`Error [${err.getApiCode()}]: ${err.message}`);
        } else if (err instanceof StrongmbError) {
            console.error('Network error:', err.message);
        }
    } 

})();